        title: "വിവരങ്ങളുടെ തിരുത്തലും അപ്‌ഡേറ്റും",
        p1: "നിങ്ങളുടെ വിവരങ്ങൾ കൃത്യവും അപ്‌ഡേറ്റ് ചെയ്തതുമായി സൂക്ഷിക്കേണ്ട ഉത്തരവാദിത്തം നിങ്ങളുടേതാണ്. ആവശ്യമുള്ളപ്പോൾ തൊഴിൽ അന്വേഷകർ സ്ഥലം, കഴിവുകൾ, പരിചയം, ശമ്പള പ്രതീക്ഷ, ലഭ്യത, ഭാഷാ മുൻഗണന എന്നിവ അപ്‌ഡേറ്റ് ചെയ്യണം.",
        p2: "ആവശ്യമുള്ളപ്പോൾ തൊഴിലുടമകൾ ജോലി നില, ശമ്പള വിശദാംശങ്ങൾ, അഭിമുഖ വിശദാംശങ്ങൾ, നിയമന നില, കമ്പനി വിശദാംശങ്ങൾ, ബന്ധപ്പെടാനുള്ള വിവരങ്ങൾ എന്നിവ അപ്‌ഡേറ്റ് ചെയ്യണം.",
