        p2: "നിയമവിരുദ്ധ ബാലവേലയോ തൊഴിൽ നിയമ ലംഘനമോ ഉൾപ്പെടുന്ന ജോലികൾ തൊഴിലുടമകൾ പോസ്റ്റ് ചെയ്യരുത്. ബാധകമായ നിയമം ലംഘിച്ച് ഒരു കുട്ടിയുടെ വ്യക്തിഗത ഡാറ്റ ശേഖരിച്ചതായി ഞങ്ങൾ കണ്ടെത്തിയാൽ, അത്തരം വിവരങ്ങൾ ഇല്ലാതാക്കുകയോ നിയന്ത്രിക്കുകയോ ചെയ്തേക്കാം.",
